package vn.svframe.svframelib.api.crafting.recipes; import vn.svframe.svframelib.api.crafting.ingredients.*; import vn.svframe.svframelib.api.crafting.outputs.SVFrameRecipeOutput; import vn.svframe.svframelib.api.util.Ref; import net.minecraft.util.Identifier; import java.util.*; import java.util.function.Predicate; public class SVFrameRecipeBlueprint { private final SVFrameRecipe main; private final SVFrameRecipeOutput result; private final Identifier id; private final Map<String,SVFrameRecipe> side=new LinkedHashMap<>(); private final ArrayList<SVFrameRecipeStation> deployed=new ArrayList<>(); private final ArrayList<String> permissions=new ArrayList<>(); public SVFrameRecipeBlueprint(SVFrameRecipe m,SVFrameRecipeOutput r){this(m,r,null);} public SVFrameRecipeBlueprint(SVFrameRecipe m,SVFrameRecipeOutput r,Identifier id){main=m;result=r;this.id=id;} public Identifier getNk(){return id;} public boolean canDisplayInRecipeBook(){return id!=null&&main instanceof VanillaBookableRecipe&&result instanceof VanillaBookableOutput;} public SVFrameRecipeOutput getResult(){return result;} public SVFrameRecipe getMainCheck(){return main;} public ArrayList<String> getSideInventoryNames(){return new ArrayList<>(side.keySet());} public SVFrameRecipe getSideCheck(String n){return side.get(n);} public boolean hasSideInventory(String n){return side.containsKey(n);} public void addSideCheck(String n,SVFrameRecipe r){side.put(n,r);} public SVFrameBlueprintInventory matches(SVFrameBlueprintInventory inv,Ref<Integer> amount){SVFrameRecipeInventory m=main.matches(inv.getMainInventory(),amount);if(m==null)return null;SVFrameBlueprintInventory out=new SVFrameBlueprintInventory(m,inv.getResultInventory().clone());for(String n:side.keySet()){SVFrameRecipeInventory source=inv.getSideInventory(n);if(source==null)return null;SVFrameRecipeInventory checked=side.get(n).matches(source,amount);if(checked==null)return null;out.addSideInventory(n,checked);}return out;} public void deploy(SVFrameRecipeStation s){if(!deployed.contains(s))deployed.add(s);SVFrameCraftingManager.deployBlueprint(this,s);} public ArrayList<SVFrameRecipeStation> getDeployedFor(){return new ArrayList<>(deployed);} public void disable(){deployed.clear();SVFrameCraftingManager.removeBlueprint(this);} public ArrayList<String> getRequiredPermissions(){return new ArrayList<>(permissions);} public void addRequiredPermission(String p){if(p!=null&&!p.isBlank()&&!permissions.contains(p))permissions.add(p);} public void clearRequiredPermissions(){permissions.clear();} public boolean checkPermissions(Predicate<String> check){for(String p:permissions)if(!check.test(p))return false;return true;} }
